function persist(){disk.markDirty();}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function activity(title,type,id){const p=project();p.activity.unshift({title,type,id,time:'刚刚',recordedAt:new Date().toISOString()});p.activity=p.activity.slice(0,20);persist();}
const tagClass=c=>({'程序':'blue','美术':'purple','策划':'green','音频':'orange','高':'red','中':'orange','低':'blue'}[c]||'green');
const tag=(t,c)=>`<span class="tag ${c||tagClass(t)}">${esc(t)}</span>`;
const button=(label,action,ic='plus',primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${icon(ic)}${label}</button>`;
const textLink=(label,target)=>`<button class="text-link" data-page="${target}">${label}${icon('right')}</button>`;
