async function renderDiagram(g,target){const container=document.getElementById(target);if(!container)return;const source=g.source;const seq=++renderSeq;container.dataset.seq=String(seq);try{const mermaid=await getMermaid();await mermaid.parse(source);const {svg}=await mermaid.render(`gf-${uid().replaceAll('-','')}`,source);if(container.isConnected&&container.dataset.seq===String(seq)){container.innerHTML=svg;container.dataset.valid='true';}}catch(e){if(container.isConnected&&container.dataset.seq===String(seq)){container.dataset.valid='false';container.innerHTML=`<div class="diagram-error"><strong>图表暂时无法绘制</strong><br>${esc(String(e.message||e).slice(0,450))}<br>请检查源码的缩进、括号与连线。你的编辑内容仍会自动保存。</div>`;}}}
function switchEditorTab(tab){editor.diagramSource=false;editor.tab=tab;const found=editor.doc.diagrams.find(g=>g.type===tab);editor.activeDiagram=found?.id||null;renderEditor();}
