function runSearch(q){const p=project(),results=[];if(q.trim())for(const [type,label]of[['tasks','任务'],['docs','文档'],['world','设定'],['characters','角色'],['assets','资源'],['bugs','问题'],['logs','日志'],['milestones','里程碑']])for(const r of p[type])if((r.title+' '+(r.content||r.description||'')).toLowerCase().includes(q.toLowerCase()))results.push({type,label,r});$('#search-results').innerHTML=results.length?results.slice(0,40).map(x=>`<button class="search-result" data-open-type="${x.type}" data-id="${x.r.id}"><span>${esc(x.r.title)}</span><small>${x.label}</small></button>`).join(''):`<div class="empty">${q?'没有找到匹配内容，试试别的关键词。':'输入关键词，开始搜索。'}</div>`;}
