 const action=el.dataset.action;if(!action)return;if(action==='close-document'){closeDocument();return;}if(action==='document-fullscreen'){documentLayout?.toggleFullscreen();return;}if(action==='document-half'){documentLayout?.destroy();documentLayout=attachDocumentLayout($('.document-panel'));return;}if(action==='close-modal'){closeModal();return;}if(action==='retry-save'){await savedToast('已保存到 Project。');return;}if(action==='reload-disk'){await reloadProjectFiles();return;}if(action==='recover-reload'){await reloadProjectFiles(true);return;}if(action==='migrate-browser'){await migrateBrowser();return;}if(action==='retry-load'){await initializeWorkspace();return;}if(action==='mobile'){$('.sidebar').classList.toggle('open');$('.mobile-backdrop').classList.toggle('open');return;}if(action==='projects')return projectsModal();if(action==='new-project')return editProject();if(action==='confirm-delete-project'){await deleteProjectFromLibrary(el.dataset.id);return;}if(action==='edit-project')return editProject(project().id);if(action==='quick-create')return quickCreate();if(action==='new-doc')return openDoc();if(action==='new-mindmap')return openDoc(null,'mindmap');if(action==='new-flowchart')return openDoc(null,'flowchart');if(action.startsWith('new-'))return editRecord(action.slice(4));if(action==='search')return searchModal();if(action==='due'){navigate('tasks');taskMode='list';taskFilter='';const tasks=project().tasks.filter(t=>t.status!=='done'&&t.due&&daysUntil(t.due)<=7).sort((a,b)=>a.due.localeCompare(b.due));modal('未来 7 天 · 任务提醒',tasks.length?tasks.map(t=>`<button class="search-result" data-open-type="tasks" data-id="${t.id}"><span>${esc(t.title)}</span><small>${dateLabel(t.due)}${daysUntil(t.due)<0?' · 已逾期':''}</small></button>`).join(''):'<div class="empty">未来 7 天没有即将到期的任务。</div>');return;}
