document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!e.defaultPrevented){e.preventDefault();if(page==='library'){$('#library-search')?.focus();return;}if(editor)dismissEditor();searchModal();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&editor){e.preventDefault();saveEditor();}if(e.key==='Escape'&&!e.defaultPrevented){if($('#modal-root').children.length)closeModal();else if(editor)closeDocument();}if(e.key==='Tab'&&e.target.id==='diagram-source'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('  ',start,end,'end');el.dispatchEvent(new Event('input',{bubbles:true}));}});
